<?php
declare(strict_types=1);require_once dirname(__DIR__).'/config/bootstrap.php';require_once __DIR__.'/_layout.php';$product=ProductRepository::findPublicBySlug(Database::connection(),trim((string)($_GET['slug']??'')));if(!$product){http_response_code(404);pageStart('Producto no encontrado');echo '<main class="wrap"><div class="panel"><h1>Esta pieza ya no está disponible.</h1><a class="btn" href="/">Volver a la colección</a></div></main>';pageEnd();exit;}pageStart((string)$product['nombre']);?>
<main class="wrap product-layout"><div class="product-photo"><img src="<?=Security::e($product['imagen_url']?:'https://placehold.co/800x1000?text=Nova')?>" alt="<?=Security::e($product['nombre'])?>"></div><div class="product-info"><span class="eyebrow">Pieza seleccionada</span><h1><?=Security::e($product['nombre'])?></h1><div class="price">$<?=number_format((float)$product['precio'],0)?> MXN</div><p class="muted"><?=nl2br(Security::e($product['descripcion']))?></p><p><strong><?=(int)$product['stock']?> disponible<?=(int)$product['stock']===1?'':'s'?></strong></p><form action="/carrito.php" method="post"><input type="hidden" name="csrf" value="<?=Security::e(Security::csrfToken())?>"><input type="hidden" name="action" value="add"><input type="hidden" name="product_id" value="<?=(int)$product['id']?>"><label>Cantidad <input class="quantity" type="number" name="quantity" min="1" max="<?=(int)$product['stock']?>" value="1"></label> <button class="btn" type="submit" <?=(int)$product['stock']<=0?'disabled':''?>>Agregar a la bolsa</button></form></div></main><?php pageEnd();?>
